221	16	\N	1	1	Two-Factor Authentication	\N	auth_totp.auth_totp_form	qweb	auth_totp/views/templates.xml	primary	{"en_US": "<t name=\\"Two-Factor Authentication\\" t-name=\\"auth_totp.auth_totp_form\\">\\n        <t t-call=\\"web.login_layout\\">\\n            <t t-set=\\"disable_footer\\">1</t>\\n            <div class=\\"oe_login_form\\">\\n                <h5 class=\\"card-title\\">Two-factor Authentication</h5>\\n                <form method=\\"POST\\" action=\\"\\" class=\\"\\">\\n                    <div class=\\"mb-2 mt-2 text-muted\\">\\n                        To login, enter below the six-digit authentication code provided by your Authenticator app.\\n                        <br/>\\n                        <a href=\\"https://www.odoo.com/documentation/master/applications/general/auth/2fa.html\\" title=\\"Learn More\\" target=\\"_blank\\">Learn More</a>\\n                    </div>\\n                    <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                    <input type=\\"hidden\\" name=\\"redirect\\" t-att-value=\\"redirect\\"/>\\n                    <div class=\\"mb-3\\">\\n                        <label class=\\"fw-bold\\" for=\\"totp_token\\">Authentication Code</label>\\n                        <input id=\\"totp_token\\" name=\\"totp_token\\" class=\\"form-control mb-2\\" autocomplete=\\"off\\" inputmode=\\"numeric\\" autofocus=\\"autofocus\\" required=\\"required\\" placeholder=\\"e.g. 123456\\"/>\\n                    </div>\\n                    <div class=\\"text-center py-2 border-top\\">\\n                        <p class=\\"alert alert-danger\\" t-if=\\"error\\" role=\\"alert\\">\\n                            <t t-esc=\\"error\\"/>\\n                        </p>\\n                    <div class=\\"mb-2 mt-2 text-muted\\">\\n                        <input type=\\"checkbox\\" name=\\"remember\\" id=\\"switch-remember\\" value=\\"1\\"/>\\n                        <label for=\\"switch-remember\\">D